+	if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
+		if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
