+		field.window = size
+	}
+	var before []string
+	if field.value != nil {
+		before = append(before, (*field.value)...)
+	}
+	model, cmd := field.MultiSelect.Update(msg)
+	if updated, ok := model.(*huh.MultiSelect[string]); ok {
