+		placements = append(placements, coreapi.ResolvedPlacement{
+			ClusterHost:  region.host,
+			Cell:         coreapi.NewOptString(region.slug),
+			Jurisdiction: coreapi.NewOptString(region.jurisdiction),
+		})
+	}
+	return placements
+}
